 "content": "def transform(grid):
    """Extend each diagonal trail of a non-background color to the edge."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    colors = {v for row in grid for v in row if v != bg}
    for color in colors:
        points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        # Find the diagonal direction indicated by adjacent same-color cells.
        directions = Counter()
        for r, c in points:
            for dr in (-1, 1):
                for dc in (-1, 1):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                        if dr == 1:
                            directions[dc] += 1
        if not directions:
            continue
        dc = directions.most_common(1)[0][0]
        # Extend from the lower endpoint in the downward direction.
        max_r = max(r for r, c in points)
        candidates = [(r, c) for r, c in points if r == max_r]
        r, c = min(candidates, key=lambda p: p[1]) if dc < 0 else max(candidates, key=lambda p: p[1])
        while 0 <= r + 1 < h and 0 <= c + dc < w:
            r, c = r + 1, c + dc
            if out[r][c] == bg:
                out[r][c] = color
    return out
